import {modelApi} from './model-api.js?v=1';
import {adminApi,adminError} from './admin-api.js?v=1';
import {createHome} from '../scene.js?v=27-models';
import {DECOR_ITEMS,DECOR_PAGES,DECOR_COLORS,modelSpec} from '../decoration-scene.js?v=9';
const root=document.querySelector('#workbench'),names=['Piggy','4010','Joey & Zakery','我们的客厅'];
const clone=x=>JSON.parse(JSON.stringify(x)),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let currentUserId=null;
let record=null,draft=null,base=null,liveRooms=null,liveCatalog=null,home=null,type='plant',room=3,selected=null,mode='single',debug=true,night=false,dirty=false,busy=false,valid=false,query='',category='',images={},epoch=0;
function spec(key=type){return modelSpec(key,draft?.catalog??{});}
function message(text,error=false){const el=document.querySelector('#model-message');if(el){el.textContent=text;el.classList.toggle('error',error);el.hidden=!text;}}
function item(){return draft.rooms[room].items.find(i=>i.id===selected)??null;}
function setDirty(){dirty=true;document.querySelector('#draft-state').textContent='有未保存修改';}
function stable(x){if(Array.isArray(x))return '['+x.map(stable).join(',')+']';if(x&&typeof x==='object')return '{'+Object.keys(x).sort().map(k=>JSON.stringify(k)+':'+stable(x[k])).join(',')+'}';return JSON.stringify(x);}
function beforeLeave(event){if(dirty){event.preventDefault();event.returnValue='';}}
window.addEventListener('beforeunload',beforeLeave);window.hasModelChanges=()=>dirty;
function setBusy(value){busy=value;document.querySelectorAll('[data-mutation]').forEach(b=>b.disabled=value);const fields=document.querySelector('#model-property-fields');if(fields)fields.disabled=value;const select=document.querySelector('#model-room');if(select)select.disabled=value;const restore=document.querySelector('#restore');if(restore&&!value)restore.disabled=!record?.previous;}
function layout(){root.innerHTML=`<header class="work-header"><div><h1>把喜欢的，摆进小家。</h1><p><span class="status-dot"></span><span id="draft-state"></span> · 第 <span id="model-version"></span> 版<br>这里管理 34 款可布置家具与墙饰。固定墙体、门窗和床暂不在此编辑。</p></div><div class="actions"><button data-mutation id="reload">重新载入</button><button data-mutation id="discard">从小屋重新开始</button><button data-mutation id="save">保存草稿</button><button data-mutation class="primary" id="publish">应用到小屋</button><button data-mutation id="restore">恢复上一版</button></div></header><div id="model-message" class="notice" role="status" aria-live="polite" hidden></div><div class="work-layout"><aside class="library" aria-label="家具模型库"><h3>家具模型库 <span class="count">34</span></h3><input id="model-search" aria-label="搜索家具" placeholder="搜索家具"><select id="model-category" aria-label="家具分类"><option value="">全部分类</option>${DECOR_PAGES.map((n,i)=>`<option value="${i}">${n}</option>`).join('')}</select><div class="library-list" id="library-list"></div></aside><section class="preview-area"><div class="preview-tools"><div class="actions"><button id="view-single">单件预览</button><button id="view-room">房间预览</button></div><div class="actions"><button id="preview-night" aria-pressed="false">切换夜晚</button><button id="preview-debug" aria-pressed="true">隐藏轮廓与路点</button></div></div><div id="model-stage" class="model-stage" aria-label="家具与房间三维预览"><div id="hotspots"></div></div><p class="preview-help">拖动旋转，滚轮或双指缩放。在房间预览中，选中已摆放家具后可点地面移动。蓝框是家具外轮廓，绿点是人物可站立的位置。</p><div class="placement-heading"><h2>房间里的家具</h2><select id="model-room" aria-label="选择布置房间">${names.map((n,i)=>`<option value="${i}" ${i===room?'selected':''}>${n}</option>`).join('')}</select></div><div class="actions" style="margin-bottom:12px"><button data-mutation id="add">＋ 摆放选中款式</button><span id="instance-count" class="count"></span></div><div class="instances" id="instances"></div></section><aside class="properties" id="properties"></aside></div>`;
 document.querySelector('#model-search').value=query;document.querySelector('#model-category').value=category;
 document.querySelector('#model-search').oninput=e=>{query=e.target.value;renderLibrary();};document.querySelector('#model-category').onchange=e=>{category=e.target.value;renderLibrary();};
 document.querySelector('#model-room').onchange=e=>{room=Number(e.target.value);selected=null;mode='room';renderProperties();renderInstances();updateScene(true);};
 document.querySelector('#view-single').onclick=()=>{mode='single';updateScene(true);};document.querySelector('#view-room').onclick=()=>{mode='room';updateScene(true);};
 document.querySelector('#preview-night').onclick=()=>{night=!night;home.setNight(night);document.querySelector('#preview-night').textContent=night?'切换白天':'切换夜晚';document.querySelector('#preview-night').setAttribute('aria-pressed',String(night));};
 document.querySelector('#preview-debug').onclick=()=>{debug=!debug;document.querySelector('#preview-debug').textContent=debug?'隐藏轮廓与路点':'显示轮廓与路点';document.querySelector('#preview-debug').setAttribute('aria-pressed',String(debug));updateScene();};
 document.querySelector('#reload').onclick=()=>reload(true);document.querySelector('#discard').onclick=()=>discard();document.querySelector('#save').onclick=()=>save();document.querySelector('#publish').onclick=()=>publish();document.querySelector('#restore').onclick=()=>restore();document.querySelector('#add').onclick=()=>addItem();
}
function renderLibrary(){const list=Object.keys(DECOR_ITEMS).filter(k=>(category===''||String(DECOR_ITEMS[k].page)===category)&&(!query||spec(k).name.includes(query)||spec(k).desc.includes(query)));document.querySelector('#library-list').innerHTML=list.length?list.map(k=>`<button class="model-card ${type===k?'active':''}" data-type="${k}" aria-pressed="${type===k}">${images[k]?`<img src="${images[k]}" alt="" width="50" height="50">`:'<span>♧</span>'}<span><b>${esc(spec(k).name)}</b><small>${spec(k).enabled===false?'已从布置菜单隐藏':DECOR_PAGES[DECOR_ITEMS[k].page]}</small></span></button>`).join(''):'<p class="empty">没有找到这款家具。</p>';document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{type=b.dataset.type;selected=null;mode='single';renderLibrary();renderProperties();renderInstances();updateScene(true);});}
function renderInstances(){const items=draft.rooms[room].items;document.querySelector('#instance-count').textContent=`${items.length} / 12 件`;document.querySelector('#instances').innerHTML=items.length?items.map(i=>`<button class="instance ${selected===i.id?'active':''}" data-instance="${i.id}" aria-pressed="${selected===i.id}"><span>${esc(spec(i.type).name)}</span><small>X ${i.x.toFixed(2)} / Z ${i.z.toFixed(2)}</small></button>`).join(''):'<p class="empty">这个房间还没有自定义家具。<br>选一款喜欢的，试着摆进来。</p>';document.querySelectorAll('[data-instance]').forEach(b=>b.onclick=()=>{selected=b.dataset.instance;type=item().type;mode='room';renderInstances();renderLibrary();renderProperties();updateScene(true);});}
function renderProperties(){const meta=spec(),current=item();document.querySelector('#properties').innerHTML=`<fieldset id="model-property-fields"><div><h2>同款默认属性</h2><p class="hint">名称与菜单设置影响同款家具。尺寸和配色会作为新家具的默认值；已有单件的独立设置优先。</p><label class="field">名称<input id="meta-name" maxlength="30" value="${esc(meta.name)}"></label><label class="field">介绍<textarea id="meta-desc" maxlength="100">${esc(meta.desc)}</textarea></label><label class="field">默认尺寸倍数<input id="meta-scale" type="number" min="0.5" max="1.8" step="0.05" value="${meta.scale??1}"></label><label class="field">默认配色<select id="meta-color">${DECOR_COLORS.map((c,i)=>`<option value="${c}" ${c===(meta.color??DECOR_COLORS[3])?'selected':''}>${['暖粉','浅绿','淡紫','奶油','雾蓝','木棕'][i]}</option>`).join('')}</select></label><div class="checks"><label><input id="meta-enabled" type="checkbox" ${meta.enabled!==false?'checked':''}>显示在布置菜单</label><label><input id="meta-collision" type="checkbox" ${(meta.collision??(!meta.wall&&type!=='rug'))?'checked':''} ${meta.wall?'disabled':''}>阻挡人物行走</label></div><p class="field">允许从菜单放入</p><div class="checks">${names.map((n,i)=>`<label><input data-room="${i}" type="checkbox" ${(!meta.rooms||meta.rooms.includes(i))&&(!meta.wall||i===3)?'checked':''} ${meta.wall&&i!==3?'disabled':''}>${n}</label>`).join('')}</div><p class="hint">隐藏款式和限制房间不会删除已经摆好的家具。</p></div><hr class="divider"><div><h2>${current?'这件家具的摆放':'摆放属性'}</h2>${current?`<p class="hint">修改仅影响当前房间里的这一件。</p><div class="two-fields"><label class="field">横向 X<input data-position="x" type="number" step="0.25" value="${current.x}"></label><label class="field">纵向 Z<input data-position="z" type="number" step="0.25" value="${current.z}" ${meta.wall?'disabled':''}></label></div><label class="field">旋转<select data-position="rotation" ${meta.wall?'disabled':''}>${[0,1,2,3].map(n=>`<option value="${n}" ${n===current.rotation?'selected':''}>${n*90}°</option>`).join('')}</select></label><label class="field">尺寸倍数<input data-position="scale" type="number" min="0.5" max="1.8" step="0.05" value="${current.scale??meta.scale??1}"></label><label class="field">配色<select data-position="color">${DECOR_COLORS.map((c,i)=>`<option value="${c}" ${c===current.color?'selected':''}>${['暖粉','浅绿','淡紫','奶油','雾蓝','木棕'][i]}</option>`).join('')}</select></label><label class="checks"><input id="item-collision" type="checkbox" ${(current.collision??meta.collision??(!meta.wall&&type!=='rug'))?'checked':''} ${meta.wall?'disabled':''}>这件家具阻挡人物</label><p id="placement-status" role="status"></p><div class="actions" style="margin-top:12px"><button data-mutation id="duplicate">复制</button><button data-mutation class="danger" id="remove">收回这件</button></div>`:'<p class="empty">从下方房间列表选中一件家具，或点击“摆放选中款式”。</p>'}</div></fieldset>`;
 for(const key of ['name','desc','scale','color','enabled','collision']){const input=document.querySelector('#meta-'+key);input.onchange=()=>{let value=input.type==='checkbox'?input.checked:input.type==='number'?Number(input.value):input.value;if(key==='scale'&&(!Number.isFinite(value)||value<.5||value>1.8)){message('尺寸倍数需在 0.5 到 1.8 之间。',true);input.value=meta.scale??1;return;}draft.catalog[type]={...draft.catalog[type],[key]:value};setDirty();renderLibrary();if(key==='scale'||key==='collision')renderProperties();updateScene();};}
 document.querySelectorAll('[data-room]').forEach(el=>el.onchange=()=>{const rooms=[...document.querySelectorAll('[data-room]:checked')].map(e=>Number(e.dataset.room));draft.catalog[type]={...draft.catalog[type],rooms};setDirty();});
 if(current){document.querySelectorAll('[data-position]').forEach(el=>el.onchange=()=>{const key=el.dataset.position,value=key==='color'?el.value:Number(el.value);if(key!=='color'&&(!Number.isFinite(value)||key==='scale'&&(value<.5||value>1.8))){message('请输入有效的位置或尺寸。',true);renderProperties();return;}current[key]=value;setDirty();renderInstances();updateScene();});document.querySelector('#item-collision').onchange=e=>{current.collision=e.target.checked;setDirty();updateScene();};document.querySelector('#remove').onclick=()=>{draft.rooms[room].items=draft.rooms[room].items.filter(i=>i.id!==selected);selected=null;setDirty();renderInstances();renderProperties();updateScene();};document.querySelector('#duplicate').onclick=()=>addItem(current);}
 setBusy(busy);
}
function updateScene(reset=false){if(!home||!draft)return;home.setDecorationEditor(-1,null);home.setDecorCatalog(draft.catalog);for(let i=0;i<4;i++)home.setDecorRoom(i,draft.rooms[i]);if(mode==='single'){home.showModelDebug(room,selected,false);const meta=spec();home.inspectDecor({id:'inspector',type,color:meta.color??DECOR_COLORS[3],scale:meta.scale??1});}else{home.inspectDecor(null);if(reset)home.setRoom(room===3?-1:room);const current=item();if(current){valid=home.canPlaceDecor(room,current);home.setDecorationEditor(room,current,change=>{if(busy||!change.item)return;Object.assign(current,change.item);setDirty();renderInstances();renderProperties();updateScene();});const el=document.querySelector('#placement-status');if(el){el.textContent=valid?'位置检查通过。':'此处可能重叠、越界或挡住通道。请移动家具，发布前需要通过检查。';el.className=valid?'position-valid':'position-invalid';}}home.showModelDebug(room,selected,debug);}
 document.querySelector('#view-single').classList.toggle('active',mode==='single');document.querySelector('#view-room').classList.toggle('active',mode==='room');
}
function addItem(source=null){if(busy)return;const meta=spec();if(!meta.enabled&&meta.enabled!==undefined||meta.rooms&&!meta.rooms.includes(room)||meta.wall&&room!==3){message('这款家具未开放给当前房间，请先调整允许的房间或显示设置。',true);return;}if(draft.rooms[room].items.length>=12){message('每个房间最多摆放 12 件家具。',true);return;}const fresh=source?{...clone(source),id:crypto.randomUUID() }:{id:crypto.randomUUID(),type,x:0,z:meta.wall?2.08:room===3?8:4,rotation:0,color:meta.color??DECOR_COLORS[3],scale:meta.scale??1};if(source&&!meta.wall){fresh.x+=.75;fresh.z+=.75;}
 // 从空闲位置开始，再用同一套寻路检查确认通道。
 if(!home.canPlaceDecor(room,fresh)){let found=false;for(let z=meta.wall?2.08:room===3?3:-3;z<=(meta.wall?2.08:room===3?11:8)&&!found;z+=.75)for(let x=room===3?-15:-5;x<(room===3?14:4);x+=.75){const p={...fresh,x,z};if(home.canPlaceDecor(room,p)){Object.assign(fresh,p);found=true;break;}}if(!found){message('当前房间找不到合适的空位，请先收回家具或选择其他房间。',true);return;}}
 draft.rooms[room].items.push(fresh);selected=fresh.id;mode='room';setDirty();renderInstances();renderProperties();updateScene(true);message('已加入草稿，可以点地面或输入数值调整位置。');}
async function reload(ask=false){if(busy)return;if(ask&&dirty&&!window.confirm('放弃当前未保存修改，载入服务器草稿吗？'))return;const token=epoch;setBusy(true);try{const next=await modelApi.snapshot();if(token!==epoch)return;record=next.state;liveRooms=clone(next.rooms);liveCatalog=clone(next.catalog);base=clone(record.draft_base??next.versions);draft=clone(record.draft??{catalog:next.catalog,rooms:next.rooms});dirty=false;selected=null;document.querySelector('#draft-state').textContent=record.draft?'草稿已保存，尚未发布':'与小屋当前布置一致';document.querySelector('#model-version').textContent=record.version;document.querySelector('#restore').disabled=!record.previous;renderLibrary();renderInstances();renderProperties();updateScene(true);message('');}catch(e){message(e.code==='40001'&&e.message?e.message:adminError(e),true);}finally{if(token===epoch){setBusy(false);document.querySelector('#restore').disabled=!record?.previous;}}}
async function save(quiet=false){if(busy||!draft)return false;const token=epoch;setBusy(true);try{const result=await modelApi.saveDraft(record.version,draft,base);if(token!==epoch)return false;record=result;dirty=false;document.querySelector('#draft-state').textContent='草稿已保存，尚未发布';document.querySelector('#model-version').textContent=record.version;if(!quiet)message('草稿已保存，家人的小屋暂时不变。');return true;}catch(e){message(e.code==='40001'&&e.message?e.message:adminError(e),true);return false;}finally{if(token===epoch)setBusy(false);}}
function validatePlacement(){home.setDecorationEditor(-1,null);home.setDecorCatalog(draft.catalog);for(let i=0;i<4;i++)home.setDecorRoom(i,draft.rooms[i]);const errors=[];for(let r=0;r<4;r++)for(const i of draft.rooms[r].items){const baseline=liveRooms?.[r]?.items?.find(v=>v.id===i.id);const physics=c=>({scale:c?.scale??1,collision:c?.collision});if(stable(i)===stable(baseline)&&stable(physics(draft.catalog[i.type]))===stable(physics(liveCatalog?.[i.type])))continue;if(!home.canPlaceDecor(r,i))errors.push({room:r,id:i.id,name:spec(i.type).name});}return errors;}
async function publish(){if(busy||!draft)return;const errors=validatePlacement();if(errors.length){room=errors[0].room;selected=errors[0].id;type=item().type;mode='room';document.querySelector('#model-room').value=room;renderInstances();renderLibrary();renderProperties();updateScene(true);message(`${names[room]}的「${errors[0].name}」未通过摆放检查，请调整后再发布。`,true);return;}if(!window.confirm('将当前模型属性和四个房间的布置应用到小屋？家人会在下一次同步时看到。')){updateScene();return;}if(dirty||!record.draft){if(!await save(true))return;}const token=epoch;setBusy(true);try{await modelApi.publish(record.version);if(token!==epoch)return;setBusy(false);await reload();message('已应用到小屋，家人会在下一次同步时看到。');}catch(e){message(e.code==='40001'&&e.message?e.message:adminError(e),true);updateScene();}finally{if(token===epoch)setBusy(false);}}
async function restore(){if(busy||!record?.previous)return;if(!window.confirm('恢复到上次发布前的模型和房间布置？当前草稿也会被清除。如果家人发布后改过布置，将停止恢复。'))return;const token=epoch;setBusy(true);try{await modelApi.restore(record.version);if(token!==epoch)return;setBusy(false);await reload();message('已恢复到上一版布置。');}catch(e){message(e.code==='40001'&&e.message?e.message:adminError(e),true);}finally{if(token===epoch)setBusy(false);}}
async function discard(){if(busy||!window.confirm('丢弃服务器草稿和当前修改，重新载入家人最新的布置？'))return;setBusy(true);try{await modelApi.discard(record.version);dirty=false;setBusy(false);await reload();message('已从小屋最新布置重新开始。');}catch(e){message(e.code==='40001'&&e.message?e.message:adminError(e),true);}finally{setBusy(false);}}
adminApi.onAuth((event,session)=>{if(event==='SIGNED_OUT'||session?.user?.id&&session.user.id!==currentUserId){epoch++;dirty=false;home?.dispose();home=null;root.innerHTML='<p class="loading">登录已退出，请返回管理台重新登录。</p>';}});
async function boot(){try{const current=await adminApi.currentUser();currentUserId=current?.id;if(!current||!(await adminApi.status()).is_admin){root.innerHTML='<p class="loading">请使用 Piggy 的管理员账号登录后打开工作台。</p>';return;}layout();try{home=createHome(document.querySelector('#model-stage'),()=>{});home.setResidentsPaused(true);images=home.getDecorPreviews(DECOR_COLORS[3]);}catch(e){home?.dispose();root.innerHTML='<p class="loading">3D 预览未能启动，请确认浏览器支持 WebGL 后刷新。</p>';console.error(e);return;}await reload();}catch(e){root.innerHTML=`<p class="loading">${esc(adminError(e))}</p>`;}}
window.addEventListener('pagehide',()=>{home?.dispose();home=null;});window.addEventListener('pageshow',event=>{if(event.persisted)location.reload();});void boot();
